// Processar decisão de escalação
const aiDecision = $('IA: Classificar Escalação').item.json.choices[0].message.content.trim().toUpperCase();
const shouldEscalate = aiDecision.includes('ESCALAR');

const context = $json.context;
const ticketId = $json.ticketId;
const intent = $json.intent;

// Determinar prioridade baseado na intenção e contexto
let priority = 'normal';
if (intent === 'RETENÇÃO' || intent === 'ESCALACAO') {
  priority = 'high';
}

// Criar resumo para nota interna
const summary = `Contexto da conversa:\n` +
  `- Assunto: ${context.ticket.subject}\n` +
  `- Canal: ${context.ticket.channel}\n` +
  `- Mensagens: ${context.conversation.messageCount}\n` +
  `- Intenção: ${intent}\n` +
  `- Última mensagem: ${$json.message.substring(0, 200)}...\n\n` +
  `Razão da escalação: ${aiDecision}`;

return {
  json: {
    shouldEscalate: shouldEscalate,
    escalated: shouldEscalate,
    priority: priority,
    reason: aiDecision,
    summary: summary,
    ticketId: ticketId,
    context: context,
    intent: intent
  }
};

// Simular envio de resposta ao Zendesk
const response = $('Processar Resposta').item.json.response;
const ticketId = $('Extrair Dados').item.json.ticketId;

console.log('\n=== RESPOSTA DO BOT ===');
console.log(`Ticket ID: ${ticketId}`);
console.log(`Resposta: ${response}`);
console.log('=======================\n');

return {
  json: {
    ticketId: ticketId,
    response: response,
    sent: true,
    simulated: true,
    timestamp: new Date().toISOString()
  }
};

// Simular escalação
const escalationData = $('Processar Escalação').item.json;
const ticketId = $('Extrair Dados').item.json.ticketId;

console.log('\n=== ESCALAÇÃO ===');
console.log(`Ticket ID: ${ticketId}`);
console.log(`Escalado: ${escalationData.escalated}`);
console.log(`Razão: ${escalationData.reason}`);
console.log(`Prioridade: ${escalationData.priority}`);
console.log('================\n');

return {
  json: {
    ticketId: ticketId,
    escalated: escalationData.escalated,
    priority: escalationData.priority,
    summary: escalationData.summary,
    simulated: true,
    timestamp: new Date().toISOString()
  }
};

// Log da execução completa
const executionLog = {
  timestamp: new Date().toISOString(),
  ticketId: $('Extrair Dados').item.json.ticketId,
  channel: $('Extrair Dados').item.json.channel,
  intent: $('Processar Classificação').item.json.intent,
  escalated: $('Verificar: Foi Escalado?').item.json?.escalated || false,
  messagePreview: $('Extrair Dados').item.json.message.substring(0, 100),
  responsePreview: $('Processar Resposta').item.json.response.substring(0, 100),
  simulated: true
};

console.log('\n=== LOG DE EXECUÇÃO ===');
console.log(JSON.stringify(executionLog, null, 2));
console.log('========================\n');

return {
  json: executionLog
};
